import requests
from bs4 import BeautifulSoup

headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}

# Define filing accessions for each quarter
filing_map = {
    '2023Q1': ('0001045810-23-000093', 'nvda-20230430.htm'),  # Q3 FY2023 10-Q
    '2023Q2': ('0001045810-23-000175', 'nvda-20230730.htm'),  # Q4 FY2023 10-Q  
    '2023Q3': ('0001045810-23-000227', 'nvda-20240128.htm'),  # Q1 FY2024 10-Q
    '2023Q4': ('0001045810-24-000124', 'nvda-20240428.htm'),  # Q2 FY2024 10-Q
    '2024Q1': ('0001045810-24-000264', 'nvda-20240728.htm'),  # Q3 FY2024 10-Q
    '2024Q2': ('0001045810-24-000316', 'nvda-20241027.htm'),  # Q4 FY2024 10-Q
}

for q, (acc, html_file) in filing_map.items():
    url = f'https://www.sec.gov/Archives/edgar/data/1045810/0001045810{acc[-6:]}/{html_file}'
    # Clean accession for path
    acc_num = acc.replace('-', '')
    url = f'https://www.sec.gov/Archives/edgar/data/1045810/{acc_num}/{html_file}'

    try:
        r = requests.get(url, headers=headers, timeout=15)
        if r.status_code == 200:
            soup = BeautifulSoup(r.text, 'html.parser')
            text = soup.get_text(separator='\n')

            # Find weighted average shares table
            for line in text.split('\n'):
                if 'weighted average' in line.lower() or 'basic and diluted' in line.lower():
                    print(f'{q}: {line.strip()[:150]}')
        else:
            print(f'{q}: HTTP {r.status_code}')
    except Exception as e:
        print(f'{q}: Error - {e}')
